export function Icon(props: IconProps) {
  const { name, size = 18, style, ...svg_props } = props;
  return (
    <svg
      aria-hidden="true"
      data-icon={name}
      fill="none"
      height={size}
      stroke="currentColor"
      strokeLinecap="round"
      strokeLinejoin="round"
      strokeWidth="1.8"
      style={{ ...style, flexShrink: 0 }}
      viewBox="0 0 24 24"
      width={size}
      {...svg_props}
    >
      {paths[name]}
    </svg>
  );
}
